  ui_story_31000601_81_dialog_content = "Huh? Mas e quanto a pegar seu remédio?",
  ui_story_31000601_82_dialog_content = "Algo me diz que esse assunto está ligado à causa da minha insônia.",
  ui_story_31000601_83_dialog_content = "Talvez resolvendo seus problemas, o barulho ao redor da Cripta também cesse.",
  ui_story_31000601_84_dialog_content = "Tudo bem, vamos falar com ela.",
  ui_story_31000601_85_dialog_content = "Por favor, ajude meu filho... Ele é inocente, eu lhe digo...",
