  ui_story_31000601_90_dialog_content = "S... Sério...?",
  ui_story_31000601_91_dialog_content = "Desculpe, mas você é realmente um médico? E você está realmente disposto a me ajudar?",
  ui_story_31000601_92_dialog_content = "E se eu te disser que meu filho já está morto? Você ainda gostaria de me ajudar?",
  ui_story_31000601_93_dialog_content = "É claro. É precisamente por esta razão que estou disposto a prestar-lhe a minha ajuda.",
  ui_story_31000601_94_dialog_content = "Ah, graças a Deus!",
  ui_story_31000601_95_dialog_content = "Finalmente, alguém disposto a provar a inocência do meu filho!",
  ui_story_31000601_96_dialog_content = "Pegue todo o meu dinheiro! Todos os meus objetos de valor! Eu pago o que você pedir, eu juro!",
  ui_story_31000601_97_dialog_content = "Não exijo nem seu dinheiro nem seus objetos de valor. Eles não me servem para nada.",
  ui_story_31000601_98_dialog_content = "Vocę năo vai... me mandar embora, vai?",
  ui_story_31000601_99_dialog_content = "P-Por favor, não entenda mal! O que ela quer dizer é que ela não precisa de nenhum tipo de compensação financeira, só isso!",
  ui_story_31000601_100_dialog_content = "Já concordamos em ajudá-lo, e é exatamente isso que planejamos fazer.",
  ui_story_31000601_101_dialog_content = "Agora, você poderia nos contar mais sobre seu filho e sua situação, por favor?",
  ui_story_31000601_102_dialog_content = "E por que as pessoas inventariam rumores sobre ele assim em primeiro lugar?",
  ui_story_31000601_103_dialog_content = "Deixe-me começar no início...",
  ui_story_31000601_104_dialog_content = "Três dias atrás, meu filho me disse que seus amigos estavam planejando explorar uma casa abandonada nos arredores da cidade.",
  ui_story_31000601_105_dialog_content = "Mas porque ele estava preocupado em me deixar em casa sozinha, ele disse a eles que não poderia ir.",
  ui_story_31000601_106_dialog_content = "Na manhã seguinte, quando percebeu que seus amigos não tinham voltado para casa, ficou preocupado.",
  ui_story_31000601_107_dialog_content = "Eu disse a ele para não se preocupar comigo e que ele deveria ir procurar seus amigos.",
  ui_story_31000601_108_dialog_content = "Essa foi a última vez que o vi.",
  ui_story_31000601_109_dialog_content = "Já se passaram três dias... Receio que seu filho e seus amigos tenham morrido há muito tempo dentro da casa.",
  ui_story_31000601_110_dialog_content = "Esperei a noite toda por ele. Na tarde do dia seguinte, ele ainda não tinha voltado para casa.",
  ui_story_31000601_111_dialog_content = "A essa altura, eu já sabia. Meu filho valorizava a amizade acima de quase qualquer outra coisa, sabe. Ele preferia morrer ao lado deles do que deixá-los para trás.",
  ui_story_31000601_112_dialog_content = "Mas ninguém mais vê isso. Em vez de querer descobrir a verdade, eles o acusaram de assassinar seus amigos e caluniaram seu bom nome!",
  ui_story_31000601_113_dialog_content = "Você parece estar mais preocupado com a inocência de seu filho do que com as circunstâncias de sua morte.",
  ui_story_31000601_114_dialog_content = "É por isso que você quer que uma autópsia seja realizada nele?",
  ui_story_31000601_115_dialog_content = "Também tínhamos sido apenas nós dois. Ele era a única família que me restava.",
  ui_story_31000601_116_dialog_content = "Você não tem ideia de como é difícil para mim aceitar que ele se foi.",
  ui_story_31000601_117_dialog_content = "Mas eu o decepcionaria se não descobrisse a verdade e não limpasse seu nome!",
  ui_story_31000601_118_dialog_content = "Eu sei que devo ter causado um grande sofrimento àquele médico, mas eu não sabia mais a quem recorrer...",
  ui_story_31000601_119_dialog_content = "Não tenho experiência médica, e o cheiro de sangue me deixa tão tonto, que não consigo nem chegar perto daquela casa...",
  ui_story_31000601_120_dialog_content = "Eu realmente quero ajudá-la, Sikare... Eu também quero descobrir a verdade por trás daquela casa mal-assombrada.",
  ui_story_31000601_121_dialog_content = "E você? Você acredita nela?",
  ui_story_31000601_122_dialog_content = "Eu não acredito em ninguém. Eu coloco minha confiança apenas em <color=#FFB400>a verdade</color>.",
  ui_story_31000601_123_dialog_content = "Quanto ao <color=#FFB400>Verdade</color> escondido neste mistério... Só encontraremos as respostas que buscamos consultando os espíritos dos mortos presos naquela casa mal-assombrada.",
  ui_story_31000601_124_dialog_content = "Por favor, diga-nos onde encontrar a casa.",
  ui_story_31000601_125_dialog_content = "Estou tão aliviado que você está disposto a ajudar.",
  ui_story_31000601_126_dialog_content = "Deixe-me levá-lo até lá imediatamente.",
  ui_story_31000601_127_dialog_content = "Assim que descobrirmos a verdade, talvez eu finalmente consiga trazê-lo para casa...",
  ui_story_31000601_128_dialog_content = "Como desejar.",
  ui_story_31000601_129_dialog_content = "Não vamos perder mais tempo. Por favor, mostre o caminho!",
  ui_story_31000601_130_dialog_content = "Mais perto e o cheiro de sangue será muito forte. Ficaremos aqui esperando por você, Sikare.",
  ui_story_31000601_131_dialog_content = "Muito bem. Eu deveria estar bem sozinha.",
  ui_story_31000601_132_dialog_content = "Por favor, descreva a aparência do seu filho para mim. Eu também precisarei coletar uma amostra de sangue se você não se opuser.",
  ui_story_31000601_133_dialog_content = "Tenha certeza, minha técnica é perfeitamente boa. Não vou tirar mais sangue do que o necessário, e você também não vai sentir o cheiro.",
  ui_story_31000601_134_dialog_content = "Entendo... deixo tudo em suas măos capazes, Doutor.",
  ui_story_31000601_135_dialog_content = "<color=#e8d9bb>Vinte minutos depois...</color>",
  ui_story_31000601_136_dialog_content = "Como estavam as coisas lá, Sikare?",
  ui_story_31000601_137_dialog_content = "Espere... Você não voltou com nada além de suas ferramentas médicas? Isso significa que o filho dela não estava lá?",
  ui_story_31000601_138_dialog_content = "Está dizendo que há uma chance de meu filho estar... vivo?",
  ui_story_31000601_139_dialog_content = "Sinto muito, mas de fato encontrei os restos do seu filho dentro da casa.",
  ui_story_31000601_140_dialog_content = "Como seu cadáver foi empilhado com muitos outros corpos, sua taxa de decomposição foi anormalmente rápida.",
  ui_story_31000601_141_dialog_content = "Como resultado, não consegui recuperar seu corpo. Eu sinto Muito.",
  ui_story_31000601_142_dialog_content = "Está tudo bem... Já estou mais do que grato por você estar disposto a ajudar...",
  ui_story_31000601_143_dialog_content = "Ainda é cedo para me agradecer. Ainda tenho mais a relatar.",
  ui_story_31000601_144_dialog_content = "Embora seu corpo já tivesse se deteriorado consideravelmente, consegui usar sua amostra de sangue para localizar alguns de seus ossos.",
  ui_story_31000601_145_dialog_content = "Através desses ossos, pude ouvir sussurros de <color=#FFB400>a verdade</color>.",
  ui_story_31000601_146_dialog_content = "<color=#e8d9bb>Há três dias...</color>",
  ui_story_31000601_147_dialog_content = "Grr... Graaah...",
  ui_story_31000601_148_dialog_content = "Graaah...!",
  ui_story_31000601_149_dialog_content = "Oh não... Vocês estão bem? Diga-me que não estou atrasado!",
  ui_story_31000601_150_dialog_content = "O que você está fazendo aqui?! Sai, depressa! Salve-se!",
  ui_story_31000601_151_dialog_content = "Se ao menos eu não tivesse sugerido explorar este lugar, não estaríamos até o pescoço em Eclipsites...",
  ui_story_31000601_152_dialog_content = "Não sei o que estão fazendo aqui, mas nenhum de vocês deveria estar pagando pelo meu erro.",
  ui_story_31000601_153_dialog_content = "É por isso que vou ficar aqui e segurá-los enquanto o resto de vocês foge! É o mínimo que posso fazer!",
  ui_story_31000601_154_dialog_content = "Você realmente acha que eu sou o tipo de cara que deixaria seus amigos para morrer?",
  ui_story_31000601_155_dialog_content = "Eu já estou aqui, não estou? Eu não vou voltar sozinho, caramba!",
  ui_story_31000601_156_dialog_content = "Se minha mãe descobrisse que eu não valorizava a vida dos meus melhores amigos...",
  ui_story_31000601_157_dialog_content = "Bem, eu não acho que ela ficaria muito feliz com isso.",
  ui_story_31000601_158_dialog_content = "Heh... O que diabos vamos fazer com você?",
  ui_story_31000601_159_dialog_content = "Juro que compenso a todos assim que sairmos daqui.",
  ui_story_31000601_160_dialog_content = "Ah! Eu farei o que for preciso para garantir que você mantenha sua palavra, então!",
  ui_story_31000601_161_dialog_content = "Graah!!",
  ui_story_31000601_162_dialog_content = "Gaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
  ui_story_31000601_163_dialog_content = "Então os Eclipses os pegaram...",
  ui_story_31000601_164_dialog_content = "De fato. Após uma breve busca, consegui encontrar vários corpos recém-falecidos... acredito que fossem amigos dele.",
  ui_story_31000601_165_dialog_content = "Cada um deles foi, sem dúvida, massacrado por Eclipsitas.",
  ui_story_31000601_166_dialog_content = "Isso significa que meu filho nunca foi um assassino...",
  ui_story_31000601_167_dialog_content = "Correto. Além disso, de acordo com minha investigação, a hora de sua morte foi um pouco posterior à de seus amigos.",
  ui_story_31000601_168_dialog_content = "Dado o estado quebrado de seus restos mortais, parece que ele sofreu muito mais ataques do que eles.",
  ui_story_31000601_169_dialog_content = "Então ele realmente aguentou até o fim...",
  ui_story_31000601_170_dialog_content = "Eu sempre soube que meu filho era um bom menino... Ele fez tudo o que podia...",
  ui_story_31000601_171_dialog_content = "Se esta foi a escolha que ele fez; se isso é o que seu coração lhe disse para fazer... Então eu posso aceitar.",
  ui_story_31000601_172_dialog_content = "Se existe reencarnação, eu escolheria ser sua mãe novamente.",
  ui_story_31000601_173_dialog_content = "Obrigado a ambos pela ajuda. Por favor, permita-me reembolsá-lo adequadamente por seus problemas.",
  ui_story_31000601_174_dialog_content = "Tenho certeza que meu filho iria querer isso também.",
  ui_story_31000601_175_dialog_content = "Basta dizer o seu preço, e farei tudo o que estiver ao meu alcance para cumpri-lo.",
  ui_story_31000601_176_dialog_content = "Nós realmente não precisamos de pagamento, senhora. Ficamos felizes em—",
  ui_story_31000601_177_dialog_content = "Muito bem, mas saiba que não há como voltar atrás em sua palavra agora.",
  ui_story_31000601_178_dialog_content = "S-Sikare! Você não disse que só estava interessado na verdade antes...?",
  ui_story_31000601_179_dialog_content = "Não, está tudo bem; toda boa ação merece uma recompensa. Por favor me diga o que você gostaria como pagamento.",
  ui_story_31000601_180_dialog_content = "Pegue este cartão de visita. Eu gostaria que você entrasse em contato com a pessoa envolvida e contasse a verdade sobre o que aconteceu aqui.",
  ui_story_31000601_181_dialog_content = "Hã?",
  ui_story_31000601_182_dialog_content = "Ela é uma jornalista excepcionalmente profissional e confiável que fará com que a verdade seja conhecida por todos, não apenas por nós.",
  ui_story_31000601_183_dialog_content = "Isso... Isso é demais... Você fez tanto por meu filho e eu...",
  ui_story_31000601_184_dialog_content = "Eu não estou fazendo isso por sua causa. Como um <color=#FFB400>médico dos mortos</color>, meu trabalho ainda não está terminado.",
  ui_story_31000601_185_dialog_content = "De certa forma, transmitir as vozes dos mortos é outra maneira de preservar os direitos daqueles que sobrevivem a eles.",
  ui_story_31000601_186_dialog_content = "Agora é hora de fazer isso.",
  ui_story_31000601_187_dialog_content = "Você nunca foi mãe de um assassino e não tinha mais motivos para aturar todos esses rumores infundados.",
  ui_story_31000601_188_dialog_content = "Sikare está absolutamente certo. Depois do que você e seu filho passaram, você não deveria ser insultado assim nunca mais.",
  ui_story_31000601_189_dialog_content = "Além disso, você disse que faria tudo ao seu alcance para pagar o que pedimos, certo?",
  ui_story_31000601_190_dialog_content = "Obrigado... Ambos. Vou me certificar de contar tudo a ela.",
  ui_story_31000601_191_dialog_content = "Bom. Agora preciso fazer uma última coisa por eles antes de partirmos.",
  ui_story_31000601_192_dialog_content = "Faria, ouça meu chamado... Abra os portões da Cripta e guie essas almas desafortunadas para seu devido lugar de descanso.",
  ui_story_31000601_193_dialog_content = "Acredito que finalmente terei uma boa noite de sono esta noite.",
  ui_story_31000601_194_dialog_content = "Que suas almas encontrem socorro no abraço da Verdade.",
  ui_story_31000602_1_dialog_content = "<color=#e8d9bb>... Gloop, gloop!</color>",
  ui_story_31000602_2_dialog_content = "Argh... Isso é nojento...",
  ui_story_31000602_3_dialog_content = "Mal consigo me mover... Mesmo que pareça que estou nadando na água, é como se eu não estivesse flutuando.",
  ui_story_31000602_4_dialog_content = "Eu estou apenas... afundando mais fundo sob esta maré negra, me afastando mais da superfície a cada segundo...",
  ui_story_31000602_5_dialog_content = "E o que são essas criaturas ao meu redor? Nunca vi nada como elas antes...",
  ui_story_31000602_6_dialog_content = "Bonito... bizarro... assustador... Estou prestes a me tornar a comida deles?",
  ui_story_31000602_7_dialog_content = "Salve... salve-me...",
  ui_story_31000602_8_dialog_content = "Bola de Neve... Bola de Neve...",
  ui_story_31000602_9_dialog_content = "É essa uma voz... me chamando?",
  ui_story_31000602_10_dialog_content = "Eu... gorgolejar, gorgolejar... Estou aqui... gorgolejar, gorgolejar...",
  ui_story_31000602_11_dialog_content = "Não tenha medo, eu estou vindo...",
  ui_story_31000602_12_dialog_content = "!",
  ui_story_31000602_13_dialog_content = "S-Sikare?",
  ui_story_31000602_14_dialog_content = "Sou eu.",
  ui_story_31000602_15_dialog_content = "Bola de Neve, o que você está fazendo aqui?",
  ui_story_31000602_16_dialog_content = "Eu... gorgolejar, gorgolejar... Eu...",
  ui_story_31000602_17_dialog_content = "Entendo. Vamos conversar mais quando chegarmos à costa.",
  ui_story_31000602_18_dialog_content = "Por favor, siga a direção para a qual estou guiando você. Sinta a flutuação das ondas.",
  ui_story_31000602_19_dialog_content = "Gorgolejar, gorgolejar...",
  ui_story_31000602_20_dialog_content = "Não tenha medo, eu vou segurar sua mão.",
  ui_story_31000602_21_dialog_content = "T-tudo bem!",
  ui_story_31000602_22_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_31000602_23_dialog_content = "Nós... Nós finalmente conseguimos sair!",
  ui_story_31000602_24_dialog_content = "Não, eu não posso deixar você sair ainda.",
  ui_story_31000602_25_dialog_content = "Você não respondeu minha pergunta anterior.",
  ui_story_31000602_26_dialog_content = "Dependendo da sua resposta, eu posso simplesmente deixar você afundar no pântano novamente.",
  ui_story_31000602_27_dialog_content = "O-Ok! Por favor, apenas me escute!",
  ui_story_31000602_28_dialog_content = "Você precisa de algo de mim, Bola de Neve?",
  ui_story_31000602_29_dialog_content = "É só que... Eu tenho visto você se trancando no seu quarto no Colossus ultimamente.",
  ui_story_31000602_30_dialog_content = "Não temos muitos dias de verão assim... Você não quer vir junto com todos para uma viagem à praia?",
  ui_story_31000602_31_dialog_content = "Desculpe, mas não tenho tais planos.",
  ui_story_31000602_32_dialog_content = "Pateta, você deveria saber que tais coisas não me interessam.",
  ui_story_31000602_33_dialog_content = "Sim, eu sei, mas agora há uma promoção especial no Hotel Tir'.",
  ui_story_31000602_34_dialog_content = "Há outros Aurorianos como você no Colosso que basicamente nunca saem para se divertir.",
  ui_story_31000602_35_dialog_content = "Provavelmente esta é a melhor oportunidade que vou ter para levar todos vocês à praia para aproveitar o mar, o sol e... os trajes de banho...",
  ui_story_31000602_36_dialog_content = "Então, Bola de Neve, você quer me ver de maiô, quer?",
  ui_story_31000602_37_dialog_content = "Não, não foi isso que eu quis dizer!",
  ui_story_31000602_38_dialog_content = "...",
  ui_story_31000602_39_dialog_content = "Então não tenho mais nada para lhe dizer. Por favor, saia.",
  ui_story_31000602_40_dialog_content = "<color=#e8d9bb>Algum tempo depois.</color>",
  ui_story_31000602_41_dialog_content = "Já fomos à praia e voltamos, mas Sikare ainda está sozinho no Colossus...",
  ui_story_31000602_42_dialog_content = "Eu deveria ir ver como ela está, pelo menos para perguntar se ela quer alguma lembrança!",
  ui_story_31000602_43_dialog_content = "Hã? Por que a porta dela está aberta?",
  ui_story_31000602_44_dialog_content = "Com licença... Hã? Ela não está aqui?",
  ui_story_31000602_45_dialog_content = "Isto é... a Caixa Preta de Sikare, Faria!",
  ui_story_31000602_46_dialog_content = "É realmente ok deixá-lo no chão assim? Talvez eu devesse pegá-lo para ela...",
  ui_story_31000602_47_dialog_content = "<color=#e8d9bb>Clique-claque! Clique-claque!</color>",
  ui_story_31000602_48_dialog_content = "... Esse negócio tá se mexendo?",
  ui_story_31000602_49_dialog_content = "<color=#e8d9bb>Clique-claque!</color>",
  ui_story_31000602_50_dialog_content = "Ahn? Ahhhhhhh—",
  ui_story_31000602_51_dialog_content = "(E assim, mergulhei na escuridão, afundando sem parar, despencando...)",
  ui_story_31000602_52_dialog_content = "(Quando recuperei a consciência, já estava profundamente atolado neste pântano, completamente incapaz de me libertar...)",
  ui_story_31000602_53_dialog_content = "Então...",
  ui_story_31000602_54_dialog_content = "Essa é a sua explicação?",
  ui_story_31000602_55_dialog_content = "Sim... Sim, e tudo é verdade!",
  ui_story_31000602_56_dialog_content = "Eu só pensei que você poderia estar um pouco solitário sozinho no Colossus.",
  ui_story_31000602_57_dialog_content = "Eu pensei que talvez você mudasse de ideia e saísse para brincar com todos!",
  ui_story_31000602_58_dialog_content = "Por favor, não use esse tipo de pensamento simplista para presumir meus pensamentos, como aqueles bocós fariam.",
  ui_story_31000602_59_dialog_content = "Pareço alguém tão inconstante?",
  ui_story_31000602_60_dialog_content = "Desculpe... eu não quis dizer isso!",
  ui_story_31000602_61_dialog_content = "Fui em frente e acabei em um lugar onde não deveria estar?",
  ui_story_31000602_62_dialog_content = "Se você realmente gostaria de saber a resposta para essa pergunta...",
  ui_story_31000602_63_dialog_content = "Que tal se juntar a mim para um tour por este lugar?",
  ui_story_31000602_64_dialog_content = "Vejo tanto medo quanto curiosidade em seus olhos. Você deve estar muito interessado neste lugar, certo?",
  ui_story_31000602_65_dialog_content = "Sim. Este pântano, e as criaturas e plantas aqui...",
  ui_story_31000602_66_dialog_content = "Nunca vi nada como eles. Este lugar poderia ser...",
  ui_story_31000602_67_dialog_content = "Isso está correto. Este é um túmulo dentro da Cripta Estrelada.",
  ui_story_31000602_68_dialog_content = "Aquelas criaturas estranhas que você viu são os guardiões daqui.",
  ui_story_31000602_69_dialog_content = "Quando você estava afundando no pântano mais cedo, se eles tivessem sentido qualquer hostilidade...",
  ui_story_31000602_70_dialog_content = "Eles teriam feito tudo ao seu alcance para eliminar você, o intruso.",
  ui_story_31000602_71_dialog_content = "Então... eu acabei de escapar por pouco com a minha vida agora?",
  ui_story_31000602_72_dialog_content = "Fique tranquilo, eles sabem que você não tem más intenções, e eles não farão nenhuma tentativa contra sua vida.",
  ui_story_31000602_73_dialog_content = "Então, Sikare, isso significa... eles sabiam desde o início que eu não era um intruso!",
  ui_story_31000602_74_dialog_content = "Claro, eles também confiam em seu próprio julgamento.",
  ui_story_31000602_75_dialog_content = "Alguns saqueadores de tumbas são hábeis em esconder suas intenções, mas você claramente carece de tal astúcia, pateta.",
  ui_story_31000602_76_dialog_content = "Sua curiosidade está quase transbordando, afogando qualquer traço de hostilidade.",
  ui_story_31000602_77_dialog_content = "É tão óbvio?",
  ui_story_31000602_78_dialog_content = "Não é uma coisa ruim, Bola de Neve.",
  ui_story_31000602_79_dialog_content = "Para um verdadeiro explorador, essas visões bizarras e fantásticas são tesouros por direito próprio.",
  ui_story_31000602_80_dialog_content = "... Você está certo sobre isso.",
  ui_story_31000602_81_dialog_content = "Agora que tive a chance de dar uma boa olhada ao redor, a paisagem aqui é verdadeiramente bela.",
  ui_story_31000602_82_dialog_content = "Uma beleza misteriosa e etérea... É tão diferente das praias movimentadas e barulhentas do verão.",
  ui_story_31000602_83_dialog_content = "Você costuma andar por aqui, Sikare?",
  ui_story_31000602_84_dialog_content = "Caminhar? \"Patrulhar\" seria um verbo mais adequado.",
  ui_story_31000602_85_dialog_content = "Como a patrulha de hoje, que rendeu uma captura muito especial—",
  ui_story_31000602_86_dialog_content = "E-Eu? Então a Caixa Preta me prendeu como se eu fosse sua presa?",
  ui_story_31000602_87_dialog_content = "Uh, falando nisso... Não deveríamos lidar com a Caixa Preta no seu quarto?",
  ui_story_31000602_88_dialog_content = "Lidar com isso?",
  ui_story_31000602_89_dialog_content = "Sim, depois de tudo...",
  ui_story_31000602_90_dialog_content = "Eu não quero te incomodar para resgatar outra pessoa!",
  ui_story_31000602_91_dialog_content = "Está preocupado em me incomodar?",
  ui_story_31000602_92_dialog_content = "Não acredito que é isso que você está realmente pensando, Bola de Neve...",
  ui_story_31000602_93_dialog_content = "Você está preocupado que se seus amigos Aurorianos invadirem precipitadamente, os resultados seriam problemáticos para você, certo?",
  ui_story_31000602_94_dialog_content = "Claro, seria melhor não ser incomodado por outras pessoas!",
  ui_story_31000602_95_dialog_content = "Você não quer ser incomodado?",
  ui_story_31000602_96_dialog_content = "Parece que você realmente gosta da paisagem daqui, Bola de Neve.",
  ui_story_31000602_97_dialog_content = "Você não quer compartilhá-lo com os outros? É raro ouvir você demonstrar tal egoísmo...",
  ui_story_31000602_98_dialog_content = "Não foi o que eu quis dizer...",
  ui_story_31000602_99_dialog_content = "Você não disse que prefere uma vida pacífica?",
  ui_story_31000602_100_dialog_content = "Se os outros Aurorians realmente vierem para cá, este lugar acabará não sendo diferente de um resort de praia.",
  ui_story_31000602_101_dialog_content = "Você considerou este aspecto? Uma justificativa digna de alguém que a Senhora Victoria considera tão altamente.",
  ui_story_31000602_102_dialog_content = "Mas deixe-me esclarecer algo - não tenho queixas sobre nenhum dos nossos companheiros, simplesmente não gosto de ambientes barulhentos.",
  ui_story_31000602_103_dialog_content = "Se alguém pudesse me acompanhar silenciosamente, seria melhor do que estar sozinho, até certo ponto.",
  ui_story_31000602_104_dialog_content = "S-Sério?",
  ui_story_31000602_105_dialog_content = "Na verdade, esta também é a primeira vez que tive a chance de apreciar quão belo é aqui na Cripta Estrelada. Nunca vi um lugar como este antes!",
  ui_story_31000602_106_dialog_content = "Se não se importa, eu gostaria de vir aqui mais vezes para sair com você!",
  ui_story_31000602_107_dialog_content = "É apenas...",
  ui_story_31000602_108_dialog_content = "Alguma preocupação, Bola de Neve?",
  ui_story_31000602_109_dialog_content = "Eu queria que houvesse uma maneira mais normal de entrar neste lugar... Não quero me encontrar afundando naquele pântano uma segunda vez!",
  ui_story_31000602_110_dialog_content = "Não se preocupe. Não importa de qual entrada você venha, ou qual tumba você entre...",
  ui_story_31000602_111_dialog_content = "Eu irei te encontrar imediatamente.",
  ui_story_31000602_112_dialog_content = "Afinal, a verdadeira entrada sempre está em minhas mãos.",
  ui_story_31000602_113_dialog_content = "Ah... Você já recuperou sua Caixa Preta? Quando você—",
  ui_story_31000602_114_dialog_content = "O que você está pensando, Bola de Neve?",
  ui_story_31000602_115_dialog_content = "Você... Você entrou aqui depois de mim?",
  ui_story_31000602_116_dialog_content = "Interessante. Por que acha isso?",
  ui_story_31000602_117_dialog_content = "Bem, você não teve tempo de voltar e pegar a Caixa Preta, e...",
  ui_story_31000602_118_dialog_content = "Você normalmente não trocaria para um <color=#FFB400>maiô</color> durante sua patrulha, certo? Então isso significa...",
  ui_story_31000602_119_dialog_content = "So, Snowball, you wish to see me in a swimsuit, do you?",
  ui_story_31000602_120_dialog_content = "No, that's not what I meant at all!",
  ui_story_31000602_121_dialog_content = "Isso é por causa do que eu disse mais cedo?",
  ui_story_31000602_122_dialog_content = "Por favor, não use esse tipo de pensamento simplista para presumir minhas intenções, como aqueles bocós fariam.",
  ui_story_31000602_123_dialog_content = "Isso é apenas o resultado da minha própria vontade, ou talvez um capricho.",
  ui_story_31000602_124_dialog_content = "Não quero ser visto por aqueles tontos, nem desejo ser julgado por eles.",
  ui_story_31000602_125_dialog_content = "Então eu só troco para o meu maiô aqui. Entendeu?",
  ui_story_31000602_126_dialog_content = "Mas... ficou ótimo em você.",
  ui_story_31000602_127_dialog_content = "Comparado com aquelas criaturas e plantas mágicas...",
  ui_story_31000602_128_dialog_content = "Eu diria até que você está mais bonita.",
  ui_story_31000602_129_dialog_content = "...",
  ui_story_31000602_130_dialog_content = "Quando eu permiti que você focasse sua curiosidade em mim?",
  ui_story_31000602_131_dialog_content = "Mesmo sem ter hostilidade, se você baixar a guarda e violar as leis da cripta...",
  ui_story_31000602_132_dialog_content = "Você ainda pode se encontrar arrastado para o abismo por esses tentáculos escuros, tornando-se uma decoração permanente aqui no túmulo.",
  ui_story_31000602_133_dialog_content = "Isso não está indo um pouco longe demais?",
  ui_story_31000602_134_dialog_content = "Medo?",
  ui_story_31000602_135_dialog_content = "Um pouco... e realmente meio preocupado!",
  ui_story_31000602_136_dialog_content = "Sua reação, Bola de Neve... é realmente muito fofa.",
  ui_story_31000602_137_dialog_content = "Não se preocupe, eu vou protegê-lo. <size=30>Afinal, o único que pode me libertar das algemas da cripta...</size>",
  ui_story_31000602_138_dialog_content = "O quê?",
  ui_story_31000602_139_dialog_content = "Eu disse... Aproxima-te. Mais perto.",
  ui_story_31000602_140_dialog_content = "Para sua segurança, Bola de Neve, enquanto estiver na cripta, você deve <color=#FFB400>sempre</color> ficar perto de mim.",
  ui_story_31000602_141_dialog_content = "Entender?",
  ui_story_31000602_142_dialog_content = "Ok, eu não vou te deixar! Prometo que vou ficar ao seu lado!"
}
return config
